"""ORD_LINE renumbering migration for Meridian CRM 4.2."""

from decimal import Decimal
from typing import Any


def _numeric_line_no(value: Any) -> Decimal:
    """Coerce a legacy LINE_NO to its numeric sorting value."""
    if value == "" or value is None:
        return Decimal(0)
    return Decimal(str(value).strip() or "0")


def renumber(lines: list[dict]) -> list[dict]:
    """Remove soft-deleted rows and renumber surviving lines per order."""
    orders: dict[str, list[tuple[int, dict]]] = {}

    for position, source_row in enumerate(lines):
        if source_row.get("DEL_FLG", "") == "Y":
            continue

        row = dict(source_row)
        order_id = str(row.get("ORD_ID", ""))
        orders.setdefault(order_id, []).append((position, row))

    result: list[dict] = []

    for order_id in sorted(orders):
        ordered_rows = sorted(
            orders[order_id],
            key=lambda item: (_numeric_line_no(item[1].get("LINE_NO", "")), item[0]),
        )

        for new_line_no, (_, row) in enumerate(ordered_rows, start=1):
            row["LINE_NO"] = new_line_no
            result.append(row)

    return result
